package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class CollectorHeartbeatJavaGoNativeMySqlTest extends CollectorHeartbeatHttpMySqlTest {
 @TempDir Path directory;
 @Test void actualGoNativeSqliteSamplerOriginalSenderJavaHttpPersistsOriginalHeartbeatAndReplay()throws Exception{
  go("prepare");var original=f.f.tx.execute(s->f.f.store.original(f.f.node));assertNotNull(original);assertEquals(1,original.revision());assertEquals(1,original.samples().size());assertEquals(f.f.now,original.samples().getFirst().receivedAt());assertEquals(0,original.samples().getFirst().input().sample().pendingObservations());assertTrue(original.samples().getFirst().input().sample().outboxBytes()>0);
  f.at.set(f.f.now.plusSeconds(600));go("replay");var next=f.f.tx.execute(s->f.f.store.original(f.f.node));assertEquals(2,next.revision());assertEquals(2,next.samples().size());assertEquals(original.samples().getFirst(),next.samples().getFirst());assertEquals(f.at.get(),next.samples().getLast().receivedAt());assertEquals(1,f.nodes.revoke(f.f.node,1));go("revoked");assertEquals(next,f.f.tx.execute(s->f.f.store.original(f.f.node)));
 }
 void go(String mode)throws Exception{
  String executable=System.getenv("V02_GO_EXEC");assertNotNull(executable,"actual Go executable required in explicit interop scope");var command=new ProcessBuilder(executable,"test","-json","./internal/outbox","-run","^TestHeartbeatJavaHTTP$","-count=1");command.directory(Path.of("../collector").toAbsolutePath().normalize().toFile());var env=command.environment();env.put("GOTOOLCHAIN","auto");env.put("GOPROXY","off");env.remove("GOROOT");env.put("VHB_BASE_URL",root.substring(0,root.indexOf("/api/collector/")).replace("http://","https://"));env.put("VHB_TOKEN",f.token);env.put("VHB_NODE",f.f.node);env.put("VHB_MODE",mode);env.put("VHB_NOW",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(f.at.get()));env.put("VHB_QUEUE",directory.resolve("queue.db").toString());env.put("VHB_FROZEN",directory.resolve("heartbeat.json").toString());Path log=Path.of("target/ri703-go-"+f.f.node+"-"+mode+".jsonl").toAbsolutePath();command.redirectErrorStream(true).redirectOutput(log.toFile());var child=command.start();if(!child.waitFor(60,TimeUnit.SECONDS)){child.destroyForcibly();child.waitFor(10,TimeUnit.SECONDS);fail("actual fictional Go heartbeat timeout");}Files.writeString(Path.of(log+".exit"),Integer.toString(child.exitValue()));assertEquals(0,child.exitValue(),()->{try{return Files.readString(log);}catch(Exception unavailable){return "actual Go child failed";}});String text=Files.readString(log);assertTrue(text.contains("\"Action\":\"pass\"")&&text.contains("TestHeartbeatJavaHTTP"));assertFalse(text.contains("\"Action\":\"skip\"")||text.contains("\"Action\":\"fail\""));
 }
}
